import { Input } from "./types.ts";
import {
  SceneUpdate,
  SceneEntity,
  SceneEntityDeletionType,
  Color,
} from "@foxglove/schemas";

export const inputs = ["/detections_3d"];
export const output = "/detections_3d/scene";

function classColor(cls: string, alpha: number): Color {
  if (cls.startsWith("red_")) {
    return { r: 1.0, g: 0.2, b: 0.2, a: alpha };
  }
  if (cls.startsWith("green_")) {
    return { r: 0.15, g: 0.95, b: 0.3, a: alpha };
  }
  if (cls === "paper_box") {
    return { r: 0.95, g: 0.65, b: 0.2, a: alpha };
  }
  return { r: 0.2, g: 0.8, b: 1.0, a: alpha };
}

export default function script(
  event: Input<"/detections_3d">,
): SceneUpdate {
  const msg = event.message;
  const stamp = event.receiveTime;
  const frameId = msg.header.frame_id || "base";
  const entities: SceneEntity[] = [];
  const halfSqrt2 = Math.SQRT1_2;

  for (let i = 0; i < msg.detections.length; i++) {
    const det = msg.detections[i];
    if (!det) {
      continue;
    }
    const hyp = det.results[0]?.hypothesis;
    const cls = hyp?.class_id ?? "obj";
    const score = hyp?.score ?? 0;
    const pos = det.bbox.center.position;
    const ori = det.bbox.center.orientation;
    const sz = det.bbox.size;
    const isCyl = cls.includes("cylinder");
    const boxColor = classColor(cls, 0.55);
    const solidColor = classColor(cls, 1.0);
    const pose = {
      position: { x: pos.x, y: pos.y, z: pos.z },
      orientation: { x: ori.x, y: ori.y, z: ori.z, w: ori.w },
    };
    const size = {
      x: Math.max(0.01, sz.x),
      y: Math.max(0.01, sz.y),
      z: Math.max(0.01, sz.z),
    };
    const cylPose = {
      position: { x: pos.x, y: pos.y, z: pos.z },
      orientation: {
        x: halfSqrt2 * (ori.x - ori.z),
        y: halfSqrt2 * (ori.w + ori.y),
        z: halfSqrt2 * (ori.x + ori.z),
        w: halfSqrt2 * (ori.w - ori.y),
      },
    };
    const cylSize = {
      x: size.z,
      y: size.y,
      z: size.x,
    };
    const maxHalf = Math.max(size.x, size.y, size.z) * 0.5;
    const label = `${cls} ${(score * 100).toFixed(0)}% (${pos.x.toFixed(2)}, ${pos.y.toFixed(2)}, ${pos.z.toFixed(2)})`;

    entities.push({
      timestamp: stamp,
      frame_id: frameId,
      id: `det_${i}`,
      lifetime: { sec: 0, nsec: 300000000 },
      frame_locked: true,
      metadata: [],
      arrows: [
        {
          pose,
          shaft_length: Math.max(0.04, size.x * 0.6),
          shaft_diameter: 0.008,
          head_length: 0.025,
          head_diameter: 0.018,
          color: { r: 1.0, g: 0.95, b: 0.1, a: 1.0 },
        },
      ],
      cubes: isCyl ? [] : [{ pose, size, color: boxColor }],
      spheres: [],
      cylinders: isCyl
        ? [{ pose: cylPose, size: cylSize, bottom_scale: 1.0, top_scale: 1.0, color: boxColor }]
        : [],
      lines: [],
      triangles: [],
      texts: [
        {
          pose: {
            position: {
              x: pos.x,
              y: pos.y,
              z: pos.z + Math.max(0.04, maxHalf + 0.04),
            },
            orientation: { x: 0, y: 0, z: 0, w: 1 },
          },
          billboard: true,
          font_size: 13,
          scale_invariant: true,
          color: solidColor,
          text: label,
        },
      ],
      models: [],
    });
  }

  const update: SceneUpdate = {
    deletions: [
      {
        timestamp: stamp,
        type: SceneEntityDeletionType.ALL,
        id: "",
      },
    ],
    entities,
  };
  return update;
}
